rows=[line.split('~') for line in DATA.splitlines() if line]
assert len(rows)==100,len(rows)
extensions={'Nasal concha','Nasal septum','Airway mucus','Airway cilium','Cricoid cartilage','Glottis','Vocal fold','Vestibular fold','Tracheal cartilage ring','Carina','Secondary bronchus','Tertiary bronchus','Respiratory bronchiole','Pulmonary capillary','Pleural cavity','Quiet expiration','Forced expiration','Intra-alveolar pressure','Intrapleural pressure','Lung compliance','Elastic recoil','Alveolar surface tension','Airway resistance','Bronchoconstriction','Bronchodilation','Oxyhemoglobin','Chloride shift','Hyperventilation','Hypoventilation','Chronic bronchitis','Lung cancer','Respiratory membrane'}
for i,(s,name,definition,detail,false,blank,answer) in enumerate(rows):
    s=int(s);clinical=name in extensions;e=f'{name}: {definition}. {detail}.'
    others=[r[1] for r in rows if r[1]!=name]
    c(s,f'Which respiratory term describes {definition}?',name,'|'.join(others[(i+j)%len(others)] for j in [7,19,31]),e,clinical)
